default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKLM:\System\Currentcontrolset\Services\Netbt\Parameters' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('NoNameReleaseOnDemand', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [int] -and [BitConverter]::ToUInt32([BitConverter]::GetBytes($current), 0) -eq [uint32]1)) {
    Write-Output 'Mismatch: HKLM:\System\Currentcontrolset\Services\Netbt\Parameters [NoNameReleaseOnDemand]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKLM:\System\Currentcontrolset\Services\Netbt\Parameters')) {
    New-Item -Path 'HKLM:\System\Currentcontrolset\Services\Netbt\Parameters' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\System\Currentcontrolset\Services\Netbt\Parameters' -Name 'NoNameReleaseOnDemand' -Value 1 -PropertyType DWord -Force | Out-Null
exit 0
